using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Automation;
using TasiaCraft;
public static partial class MediaBinTest {
 static TextBlock FailureStatus(MediaSourcePreview w){return Tree(w).OfType<TextBlock>().First(t=>AutomationProperties.GetAutomationId(t)=="MediaPreview.Status");}
 static Slider FailureSeek(MediaSourcePreview w){return Tree(w).OfType<Slider>().First(t=>AutomationProperties.GetAutomationId(t)=="MediaPreview.Seek");}
 static void FailureTests(Editor editor,Project p,LivePreview main,byte[] pixels,byte[] export){
  Reset(editor,p);string baseline=json.Serialize(P(editor));double head=(double)Field(editor,"head");var selected=Field(editor,"selected");string path=Path.Combine(root,"retry-image.png");File.WriteAllText(path,"broken image");var media=new TasiaCraft.Media{Path=path,Name="Retry image",Kind="image",Width=320,Height=180,Duration=1};Exception failure=null;MediaSourcePreview seen=null;
  editor.Dispatcher.BeginInvoke(new Action(()=>{try{
   seen=Application.Current.Windows.OfType<MediaSourcePreview>().Single();string error=FailureStatus(seen).Text;Check(error.StartsWith("Image preview failed:"),"corrupt image opens with visible decode error");if(PreviewButton(seen,"Play").IsEnabled){ClickPreview(seen,"Play");File.WriteAllText(Path.Combine(root,"failure-baseline.json"),json.Serialize(new{before=error,after=FailureStatus(seen).Text,playing=seen.Viewer.IsPlaying}));ClickPreview(seen,"Stop");}Check(!PreviewButton(seen,"Play").IsEnabled&&!PreviewButton(seen,"Stop").IsEnabled&&!FailureSeek(seen).IsEnabled,"failed source disables transport and seeking");Check(PreviewButton(seen,"Retry").IsEnabled,"failed source exposes enabled Retry");ClickPreview(seen,"Play");ClickPreview(seen,"Stop");FailureSeek(seen).Value=.5;Check(!seen.Viewer.IsPlaying&&seen.Viewer.Position==0,"failed source ignores invoked transport and seek handlers");Check(FailureStatus(seen).Text==error,"ordinary commands cannot overwrite persistent error");ClickPreview(seen,"Retry");Check(!PreviewButton(seen,"Play").IsEnabled&&FailureStatus(seen).Text.StartsWith("Image preview failed:"),"retry of unchanged corrupt source remains failed");Check(File.ReadAllText(path)=="broken image","failed retries preserve source bytes");
   File.Copy(Path.Combine(root,"red.png"),path,true);ClickPreview(seen,"Retry");Check(PreviewButton(seen,"Play").IsEnabled&&PreviewButton(seen,"Stop").IsEnabled&&FailureSeek(seen).IsEnabled&&!PreviewButton(seen,"Retry").IsEnabled,"repair and Retry restore transport eligibility");Check(!FailureStatus(seen).Text.StartsWith("Image preview failed:")&&seen.Viewer.Position==0&&!seen.Viewer.IsPlaying,"successful retry clears error and starts paused at zero");seen.Viewer.UpdateLayout();var bmp=new RenderTargetBitmap(320,180,96,96,PixelFormats.Pbgra32);bmp.Render(seen.Viewer.Stage);byte[] frame=new byte[320*180*4];bmp.CopyPixels(frame,320*4,0);Check(frame[(90*320+160)*4+2]>200,"repaired source renders fresh red pixels");ClickPreview(seen,"Play");Check(seen.Viewer.IsPlaying,"recovered source can play");ClickPreview(seen,"Stop");Check(!seen.Viewer.IsPlaying&&seen.Viewer.Position==0,"recovered source can stop");
   File.Delete(path);seen.Viewer.Seek(.25);Check(!PreviewButton(seen,"Play").IsEnabled&&!seen.Viewer.IsPlaying,"source removed after opening enters failure state");ClickPreview(seen,"Retry");Check(!PreviewButton(seen,"Play").IsEnabled&&PreviewButton(seen,"Retry").IsEnabled,"retry of absent source remains safely failed");File.Copy(Path.Combine(root,"blue.png"),path,true);ClickPreview(seen,"Retry");Check(PreviewButton(seen,"Play").IsEnabled,"source can recover after removal and replacement");seen.Viewer.UpdateLayout();bmp=new RenderTargetBitmap(320,180,96,96,PixelFormats.Pbgra32);bmp.Render(seen.Viewer.Stage);bmp.CopyPixels(frame,320*4,0);Check(frame[(90*320+160)*4]>200&&frame[(90*320+160)*4+2]<30,"second retry bypasses stale image URI cache");
  }catch(Exception ex){failure=ex;}finally{if(seen!=null)seen.Close();}}));new MediaSourcePreview(media){Owner=editor}.ShowDialog();if(failure!=null)throw failure;Check(seen!=null&&seen.Released&&!seen.Viewer.IsPlaying,"closing recovered source releases playback");
  string videoPath=Path.Combine(root,"retry-video.mp4");File.WriteAllText(videoPath,"not a video");var video=new TasiaCraft.Media{Path=videoPath,Name="Broken video",Kind="video",Width=320,Height=180,HasAudio=true,Duration=1};seen=null;failure=null;
  editor.Dispatcher.BeginInvoke(new Action(async()=>{try{seen=Application.Current.Windows.OfType<MediaSourcePreview>().Single();for(int i=0;i<30&&PreviewButton(seen,"Play").IsEnabled;i++)await Task.Delay(100);Check(!PreviewButton(seen,"Play").IsEnabled&&FailureStatus(seen).Text.Contains("cannot open"),"asynchronous decoder failure disables playback and shows error");string error=FailureStatus(seen).Text;ClickPreview(seen,"Play");Check(!seen.Viewer.IsPlaying&&FailureStatus(seen).Text==error,"failed video cannot claim successful playback");Check(File.ReadAllText(videoPath)=="not a video","failed video preserves source bytes");}catch(Exception ex){failure=ex;}finally{if(seen!=null)seen.Close();}}));new MediaSourcePreview(video){Owner=editor}.ShowDialog();if(failure!=null)throw failure;Check(seen!=null&&seen.Released,"failed decoder closes cleanly");
  Check(json.Serialize(P(editor))==baseline&&Undos(editor)==0&&!(bool)Field(editor,"dirty")&&(double)Field(editor,"head")==head&&Field(editor,"selected")==selected,"failure and retries preserve editor project history head and selection");Check(Preview(main,P(editor)).SequenceEqual(pixels)&&Export(P(editor),"failure-preserved").SequenceEqual(export),"failure workflow preserves main preview and decoded export");string save=Path.Combine(root,"failure-preserved.tasiaproj");Engine.Save(P(editor),save);Check(json.Serialize(Engine.Load(save))==baseline,"failure workflow preserves save and reopen");
 }
}
